SELECT COUNT(*)
  FROM TB_INV001
 WHERE WERKS = #{WERKS}
   AND MATNR = #{MATNR}
   AND IND_BCD = #{IND_BCD}
   AND NVL(UCFMTY_FLG, 'N') = 'Y'

SELECT a.SEQ, a.INSPR_DT, SUBSTR(a.INSPR_TM, 0, 2) || ':' || SUBSTR(a.INSPR_TM, 3, 2) || '~' || SUBSTR(a.INSPR_TM, 5, 2) || ':' || SUBSTR(a.INSPR_TM, 7, 2) AS INSPR_TM, CASE WHEN a.INSTD_CFG = 'Y' THEN a.INSPR_NM || ' (대근)' ELSE INSPR_NM END AS INSPR_NM, a.INSTD_CFG, a.MATNR, (SELECT MATNR_NM FROM TB_QLT030 WHERE MATNR = a.MATNR) AS MATNR_NM, (SELECT BS_WGT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS BS_WGT, (SELECT CLSF_STCNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_STCNT, (SELECT CLSF_MCNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_MCNT, (SELECT CLSF_CTCNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_CTCNT, (SELECT CLSF_ROLL_CNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_ROLL_CNT, a.MACH_CD, a.PART_DIV, a.CREATEUSER, a.CREATEDATE as CLSF_INPUTDT, a.UPDATEUSER, a.UPDATEDATE as CLSF_MODDT, a.RMK1 AS A_RMK1, a.RMK2 AS A_RMK2, a.RMK3 AS A_RMK3, b.P_SEQ, b.CLSF_LARGE, b.CLSF_SMALL, b.CLSF_RST_VAL, b.RMK1 AS B_RMK1, b.RMK2 AS B_RMK2, b.RMK3 AS B_RMK3 FROM TB_QLT031 a, TB_QLT032 b WHERE a.SEQ = b.P_SEQ
AND a.MATNR = #{SCH_MATNR}
AND a.INSPR_NM LIKE '%' || #{SCH_INSPR_NM} || '%'
AND INSPR_TM = #{SCH_INSPR_TM}
AND a.INSPR_DT BETWEEN #{SCH_SDATE} AND #{SCH_EDATE}
AND a.INSPR_NM = #{INSPR_NM}
AND a.MATNR = #{SCH_MATNR}
AND a.INSPR_DT = #{SCH_INSPR_DT}
AND a.INSPR_TM = #{SCH_INSPR_TM}
AND a.INSPR_NM LIKE '%' || #{SCH_INSPR_NM} || '%'
AND a.MACH_CD IN ( 'TRA04', 'TRA05')
AND a.MACH_CD = #{SCH_MACH_CD}
AND a.PART_DIV = #{SCH_PART_DIV}
AND b.CLSF_LARGE = #{CLSF_LARGE}
AND b.P_SEQ = #{QLT31_SEQ}
AND a.MATNR = #{CHK_MATNR}
AND a.INSPR_DT = #{CHK_INSPR_DT}
AND a.INSPR_TM = #{CHK_INSPR_TM}
AND a.MACH_CD IN ( 'TRA04', 'TRA05')
AND a.MACH_CD = #{CHK_MACH_CD}
AND a.PART_DIV = #{CHK_PART_DIV}
ORDER BY b.SEQ ASC

SELECT MATNR, MATNR_NM, MACH_CD, PART_DIV, BS_WGT, CLSF_STCNT, CLSF_MCNT, CLSF_CTCNT, CLSF_ROLL_CNT, CREATEUSER, CREATEDATE, UPDATEUSER, UPDATEDATE, RMK1, RMK2, RMK3 FROM TB_QLT030 WHERE 1 = 1
AND MATNR = #{SCH_MATNR}
AND MACH_CD IN ( 'TRA04', 'TRA05')
AND MACH_CD = #{SCH_MACH_CD}
AND PART_DIV = #{SCH_PART_DIV}
AND MATNR = #{SEL_MATNR}
AND MACH_CD = #{SEL_MACH_CD}
AND PART_DIV = #{SEL_PART_DIV}
ORDER BY MATNR ASC

{
	CALL SP_QLT30_S01(
		#{P_SEND_PARAM, mode=IN, jdbcType=VARCHAR, javaType=String},
		#{P_SUCCESS, mode=OUT, jdbcType=VARCHAR, javaType=String},
		#{P_ERR_MSG, mode=OUT, jdbcType=VARCHAR, javaType=String}
	)
}

{
	CALL SP_QLT31_S01(
			#{P_TYPE, mode=IN, jdbcType=VARCHAR, javaType=String},
			#{P_SEND_PARAM, mode=IN, jdbcType=VARCHAR, javaType=String},
			#{P_SUCCESS, mode=OUT, jdbcType=VARCHAR, javaType=String},
			#{P_CODE, mode=OUT, jdbcType=VARCHAR, javaType=String},
			#{P_MSG, mode=OUT, jdbcType=VARCHAR, javaType=String},
			#{P_RS_LIST, mode=OUT, jdbcType=CURSOR, javaType=ResultSet, resultMap=resultMap}
	)
}

SELECT a.SEQ, a.MATNR, b.MATNR_NM, b.MACH_CD, b.PART_DIV, a.INSPR_DT, a.INSPR_TM, a.INSPR_NM, a.INSTD_CFG, a.CREATEUSER, a.CREATEDATE, a.UPDATEUSER, a.UPDATEDATE FROM TB_QLT031 a, TB_QLT030 b WHERE a.MATNR = b.MATNR
AND a.MATNR = #{SCH_MATNR}
AND a.INSPR_NM LIKE '%' || #{SCH_INSPR_NM} || '%'
AND b.PART_DIV = #{SCH_PART_DIV}
AND b.MACH_CD IN ( 'TRA04', 'TRA05')
AND b.MACH_CD = #{SCH_MACH_CD}
AND b.INSPR_TM = #{SCH_INSPR_TM}
ORDER BY a.SEQ DESC
